SELECT DEPT, SUM(SAL) AS TOTAL
  FROM EMP
 GROUP BY DEPT;

SELECT MAX(SUM(SAL)) AS MAX_TOTAL
  FROM EMP
 GROUP BY DEPT;

SELECT MAX(ENAME) AS A,
       MIN(ENAME) AS B
  FROM EMP;

SELECT SUBSTR(PCODE, 1, 1) AS GRP, SUM(PRICE) AS TOTAL
  FROM PROD
 GROUP BY SUBSTR(PCODE, 1, 1);

SELECT COUNT(*) AS CNT
  FROM EMP
HAVING COUNT(*) > 10;
